assert len(records)==16
for r in records:
    assert all(v is not None for v in r['axis'].values())
    assert len(r['description'].split())>=110,(r['id'],len(r['description'].split()))
    changes.append(change(D,'societies',r))
    changes.append(change(D,'decisions',retained_decision(r,r['qualification_basis'])))
write_revision(1,changes,'2026-10-17 user correction: prioritize popular multimedia and replace lore-gap omissions with transparent best guesses. Sixteen individually scoped cases reopened; all prior decisions preserved in before values.')
